*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html, body { height: 100%; }

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "Helvetica Neue", system-ui, sans-serif;
  background: #0a0e1a;
  color: #ffffff;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 40px 20px;
  overflow-x: hidden;
  transition: background 1.2s cubic-bezier(0.4, 0, 0.2, 1);
  position: relative;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body::before {
  content: '';
  position: fixed;
  inset: 0;
  background:
    radial-gradient(ellipse 50% 50% at 20% 20%, rgba(244, 162, 97, 0.12), transparent),
    radial-gradient(ellipse 60% 60% at 80% 80%, rgba(99, 102, 241, 0.12), transparent);
  pointer-events: none;
  z-index: 0;
}

body.theme-clear  { background: linear-gradient(135deg, #2a3a6a 0%, #3a2a5a 50%, #5a3a4a 100%); }
body.theme-cloudy { background: linear-gradient(135deg, #1f2a3a 0%, #161e2c 50%, #0c1018 100%); }
body.theme-rain   { background: linear-gradient(135deg, #15243e 0%, #0c1626 50%, #050a14 100%); }
body.theme-snow   { background: linear-gradient(135deg, #2a3a5a 0%, #1c2438 50%, #101828 100%); }
body.theme-storm  { background: linear-gradient(135deg, #1f1432 0%, #120a1f 50%, #08050f 100%); }
body.theme-fog    { background: linear-gradient(135deg, #3a4554 0%, #252d3a 50%, #161c26 100%); }

.card {
  width: 960px;
  max-width: 100%;
  background: rgba(255, 255, 255, 0.035);
  backdrop-filter: blur(40px) saturate(180%);
  -webkit-backdrop-filter: blur(40px) saturate(180%);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 28px;
  padding: 52px 60px;
  box-shadow:
    0 30px 80px -20px rgba(0, 0, 0, 0.5),
    inset 0 1px 0 rgba(255, 255, 255, 0.06);
  position: relative;
  z-index: 1;
  animation: cardIn 0.7s cubic-bezier(0.2, 0.8, 0.2, 1);
}

@keyframes cardIn {
  from { opacity: 0; transform: translateY(16px) scale(0.985); }
  to   { opacity: 1; transform: translateY(0) scale(1); }
}

@keyframes fadeUp {
  from { opacity: 0; transform: translateY(8px); }
  to   { opacity: 1; transform: translateY(0); }
}

@keyframes draw  { to { stroke-dashoffset: 0; } }
@keyframes fadeIn{ to { opacity: 1; } }
@keyframes spin  { to { transform: rotate(360deg); } }

.loading, .error {
  min-height: 400px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 18px;
}

.spinner {
  width: 32px;
  height: 32px;
  border: 2px solid rgba(255, 255, 255, 0.1);
  border-top-color: rgba(255, 255, 255, 0.7);
  border-radius: 50%;
  animation: spin 0.8s linear infinite;
}

.loading-text {
  font-size: 13px;
  color: rgba(255, 255, 255, 0.4);
  letter-spacing: 0.04em;
}

.error-icon {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.08);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 4px;
}

.error-icon svg {
  width: 24px;
  height: 24px;
  stroke: rgba(255, 255, 255, 0.55);
  stroke-width: 1.5;
  fill: none;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.error-title {
  font-size: 20px;
  font-weight: 600;
  color: rgba(255, 255, 255, 0.92);
  letter-spacing: -0.01em;
}

.error-text {
  font-size: 14px;
  color: rgba(255, 255, 255, 0.45);
  max-width: 360px;
  text-align: center;
  line-height: 1.5;
}

.header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 36px;
  gap: 24px;
  animation: fadeUp 0.5s 0.1s ease-out backwards;
}

.location {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}

.location-name {
  font-size: 40px;
  font-weight: 700;
  letter-spacing: -0.03em;
  line-height: 1.05;
  color: #ffffff;
}

.location-date {
  font-size: 16px;
  color: rgba(255, 255, 255, 0.55);
  font-weight: 400;
  margin-top: 6px;
  letter-spacing: -0.005em;
}

.coords {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  color: rgba(255, 255, 255, 0.32);
  margin-top: 10px;
  font-family: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  letter-spacing: 0.04em;
}

.coords svg {
  width: 10px;
  height: 10px;
  opacity: 0.55;
}

.badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 7px 13px;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 100px;
  font-size: 10px;
  color: rgba(255, 255, 255, 0.7);
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  white-space: nowrap;
}

.badge-dot {
  width: 6px;
  height: 6px;
  background: #4ade80;
  border-radius: 50%;
  box-shadow: 0 0 8px rgba(74, 222, 128, 0.7);
}

.main {
  display: grid;
  grid-template-columns: 200px 1fr;
  gap: 48px;
  align-items: center;
  padding: 12px 0 44px;
  animation: fadeUp 0.5s 0.2s ease-out backwards;
}

.icon-wrap {
  width: 200px;
  height: 200px;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}

.icon-glow {
  position: absolute;
  inset: 8%;
  background: radial-gradient(circle, currentColor, transparent 60%);
  filter: blur(24px);
  opacity: 0.4;
  z-index: 0;
}

.icon-wrap svg {
  position: relative;
  z-index: 1;
  width: 100%;
  height: 100%;
}

.info {
  display: flex;
  flex-direction: column;
  gap: 24px;
  min-width: 0;
}

.condition {
  font-size: 30px;
  font-weight: 500;
  letter-spacing: -0.02em;
  line-height: 1.15;
  color: rgba(255, 255, 255, 0.95);
}

.temps {
  display: flex;
  align-items: stretch;
  gap: 36px;
}

.temp {
  display: flex;
  flex-direction: column;
  gap: 8px;
  flex: 1;
  min-width: 0;
}

.temp-label {
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  color: rgba(255, 255, 255, 0.4);
  font-weight: 600;
}

.temp-value {
  font-size: 64px;
  font-weight: 200;
  line-height: 0.95;
  letter-spacing: -0.045em;
  color: #ffffff;
  display: flex;
  align-items: flex-start;
  font-variant-numeric: tabular-nums;
}

.temp-unit {
  font-size: 22px;
  font-weight: 300;
  margin-top: 8px;
  margin-left: 4px;
  color: rgba(255, 255, 255, 0.5);
  letter-spacing: 0;
}

.temp-low { opacity: 0.55; }
.temp-low .temp-value { color: rgba(255, 255, 255, 0.8); }

.divider {
  height: 1px;
  background: linear-gradient(to right, transparent, rgba(255, 255, 255, 0.12) 15%, rgba(255, 255, 255, 0.12) 85%, transparent);
  margin: 0 0 28px;
  animation: fadeUp 0.5s 0.3s ease-out backwards;
}

.hourly { animation: fadeUp 0.5s 0.4s ease-out backwards; }

.hourly-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 22px;
  gap: 16px;
  flex-wrap: wrap;
}

.hourly-title {
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.22em;
  color: rgba(255, 255, 255, 0.4);
  font-weight: 600;
}

.hourly-meta {
  display: flex;
  gap: 18px;
  font-size: 10px;
  color: rgba(255, 255, 255, 0.5);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  font-weight: 600;
}

.hourly-meta-item { display: flex; align-items: center; gap: 6px; }

.hourly-meta-dot {
  width: 8px;
  height: 2px;
  border-radius: 1px;
  background: currentColor;
}

.chart {
  position: relative;
  height: 150px;
  width: 100%;
}

.chart svg {
  width: 100%;
  height: 100%;
  overflow: visible;
  display: block;
}

.chart .line {
  fill: none;
  stroke-width: 2.2;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-dasharray: 2000;
  stroke-dashoffset: 2000;
  animation: draw 1.8s 0.2s cubic-bezier(0.4, 0, 0.2, 1) forwards;
}

.chart .fill {
  opacity: 0;
  animation: fadeIn 1.2s 0.6s ease-out forwards;
}

.chart .point {
  opacity: 0;
  animation: fadeIn 0.3s ease-out forwards;
}

.chart .grid-line {
  stroke: rgba(255, 255, 255, 0.05);
  stroke-width: 1;
  stroke-dasharray: 2 4;
}

.chart .label {
  fill: rgba(255, 255, 255, 0.45);
  font-size: 11px;
  font-family: inherit;
  font-weight: 500;
  letter-spacing: 0.05em;
}

.chart .temp-label {
  fill: rgba(255, 255, 255, 0.85);
  font-size: 11px;
  font-weight: 600;
  font-family: inherit;
  font-variant-numeric: tabular-nums;
}

@media (max-width: 1000px) {
  .card { padding: 40px 32px; }
  .main { grid-template-columns: 160px 1fr; gap: 32px; }
  .icon-wrap { width: 160px; height: 160px; }
  .location-name { font-size: 32px; }
  .temp-value { font-size: 52px; }
  .condition { font-size: 24px; }
}

