  const ICON_COLORS = {
    clear:  '#FFC371',
    cloudy: '#CBD5E1',
    rain:   '#60A5FA',
    snow:   '#E0F2FE',
    storm:  '#FCD34D',
    fog:    '#CBD5E1',
  };

  function escapeHtml(s) {
    return String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  }

  function formatDate(d) {
    return new Date(d + 'T00:00:00Z').toLocaleDateString('en-US', {
      weekday: 'long', year: 'numeric', month: 'long', day: 'numeric', timeZone: 'UTC'
    });
  }

  function formatCoord(v, isLat) {
    const abs = Math.abs(v);
    const deg = Math.floor(abs);
    const min = Math.floor((abs - deg) * 60);
    const dir = isLat ? (v >= 0 ? 'N' : 'S') : (v >= 0 ? 'E' : 'W');
    return `${deg}° ${min.toString().padStart(2, '0')}' ${dir}`;
  }

  function smoothPath(points) {
    if (points.length < 2) return '';
    const t = 0.2;
    let d = `M ${points[0].x.toFixed(2)} ${points[0].y.toFixed(2)}`;
    for (let i = 0; i < points.length - 1; i++) {
      const p0 = points[i - 1] || points[i];
      const p1 = points[i];
      const p2 = points[i + 1];
      const p3 = points[i + 2] || p2;
      const cp1x = p1.x + (p2.x - p0.x) * t;
      const cp1y = p1.y + (p2.y - p0.y) * t;
      const cp2x = p2.x - (p3.x - p1.x) * t;
      const cp2y = p2.y - (p3.y - p1.y) * t;
      d += ` C ${cp1x.toFixed(2)} ${cp1y.toFixed(2)}, ${cp2x.toFixed(2)} ${cp2y.toFixed(2)}, ${p2.x.toFixed(2)} ${p2.y.toFixed(2)}`;
    }
    return d;
  }

  async function load() {
    try {
      const res = await fetch(url);
      if (!res.ok) throw new Error('HTTP ' + res.status);
      const data = await res.json();
      if (!data.daily || !data.daily.time || !data.daily.time.length) throw new Error('No daily data');
      const idx = data.daily.time.indexOf(date);
      if (idx === -1) throw new Error('Date not in response');

      const max = data.daily.temperature_2m_max[idx];
      const min = data.daily.temperature_2m_min[idx];
      const code = data.daily.weather_code[idx];

      const hours = data.hourly.time
        .map((t, i) => ({ time: t, temp: data.hourly.temperature_2m[i] }))
        .filter(h => h.time.startsWith(date));

      if (!hours.length) throw new Error('No hourly data');

      const info = CODES[code] || ['Unknown conditions', 'cloudy', 'cloud'];
      const [label, theme, icon] = info;
      document.body.className = `theme-${theme}`;
      document.title = `Weather — ${name}`;

      render(name, date, lat, lon, max, min, label, theme, icon, hours, isPast);
    } catch (e) {
      renderError();
    }
  }

  function renderError() {
