            <circle cx="12" cy="12" r="10"/>
            <line x1="12" y1="8" x2="12" y2="13"/>
            <line x1="12" y1="16" x2="12.01" y2="16"/>
          </svg>
        </div>
        <div class="error-title">Unable to load weather data</div>
        <div class="error-text">We couldn't fetch the forecast for this location and date. Please check your connection and try again.</div>
      </div>
    `;
  }

  function render(name, date, lat, lon, max, min, label, theme, icon, hours, isPast) {
    const dateStr = formatDate(date);
    const coordStr = `${formatCoord(lat, true)} · ${formatCoord(lon, false)}`;

    document.getElementById('content').innerHTML = `
      <div class="header">
        <div class="location">
          <div class="location-name">${escapeHtml(name)}</div>
          <div class="location-date">${dateStr}</div>
          <div class="coords">
            <svg viewBox="0 0 16 16" fill="currentColor">
              <path d="M8 1C5.24 1 3 3.24 3 6c0 3.75 5 9 5 9s5-5.25 5-9c0-2.76-2.24-5-5-5zm0 7a2 2 0 110-4 2 2 0 010 4z"/>
            </svg>
            ${coordStr}
          </div>
        </div>
        <div class="badge">
          <span class="badge-dot"></span>
          ${isPast ? 'Historical' : 'Forecast'}
        </div>
      </div>

      <div class="main">
        <div class="icon-wrap" style="color: ${ICON_COLORS[theme] || '#CBD5E1'}">
          <div class="icon-glow"></div>
          ${ICONS[icon] || ICONS.cloud}
        </div>
        <div class="info">
          <div class="condition">${label}</div>
          <div class="temps">
            <div class="temp">
              <div class="temp-label">High</div>
              <div class="temp-value">${Math.round(max)}<span class="temp-unit">°C</span></div>
            </div>
            <div class="temp temp-low">
              <div class="temp-label">Low</div>
              <div class="temp-value">${Math.round(min)}<span class="temp-unit">°C</span></div>
            </div>
          </div>
        </div>
      </div>

      <div class="divider"></div>

      <div class="hourly">
        <div class="hourly-header">
          <div class="hourly-title">Hourly Temperature · 24 Hours (UTC)</div>
          <div class="hourly-meta">
            <div class="hourly-meta-item" style="color:#FFC371"><span class="hourly-meta-dot"></span> High</div>
            <div class="hourly-meta-item" style="color:#94A3B8"><span class="hourly-meta-dot"></span> Low</div>
          </div>
        </div>
        <div class="chart" id="chart"></div>
      </div>
    `;

    const chartEl = document.getElementById('chart');
    const H = 150;
    const renderChart = (W) => {
      if (W > 0) chartEl.innerHTML = buildChartSvg(hours, min, max, W, H);
    };
    renderChart(chartEl.clientWidth || 800);

    if (typeof ResizeObserver !== 'undefined') {
      new ResizeObserver(entries => renderChart(entries[0].contentRect.width)).observe(chartEl);
    } else {
      window.addEventListener('resize', () => renderChart(chartEl.clientWidth || 800));
    }
  }

  function buildChartSvg(hours, dailyMin, dailyMax, W, H) {
    const padX = 20, padY = 30;
    const w = W - padX * 2, h = H - padY * 2;

    const temps = hours.map(x => x.temp);
    let tMin = Math.min.apply(null, temps.concat([dailyMin]));
    let tMax = Math.max.apply(null, temps.concat([dailyMax]));
    if (tMin === tMax) { tMin -= 1; tMax += 1; }
    const range = tMax - tMin;
    const pad = range * 0.2;
    const yMin = tMin - pad;
    const yMax = tMax + pad;
    const yRange = yMax - yMin;

    const points = hours.map((hr, i) => {
      const x = padX + (i / Math.max(1, hours.length - 1)) * w;
      const y = padY + (1 - (hr.temp - yMin) / yRange) * h;
      return { x, y, temp: hr.temp, hour: i };
    });

    const linePath = smoothPath(points);
    const last = points[points.length - 1];
    const first = points[0];
    const baseY = H - 18;
    const fillPath = linePath + ` L ${last.x.toFixed(2)} ${baseY} L ${first.x.toFixed(2)} ${baseY} Z`;

    const gridLines = [];
    for (let i = 0; i <= 3; i++) {
      const y = padY + (i / 3) * h;
      gridLines.push(`<line class="grid-line" x1="${padX}" y1="${y.toFixed(2)}" x2="${(W - padX).toFixed(2)}" y2="${y.toFixed(2)}"/>`);
    }

    const labelIndices = points.map((_, i) => i).filter(i => i % 3 === 0 || i === points.length - 1);
    const hourLabels = labelIndices.map(i => {
      const p = points[i];
      return `<text class="label" x="${p.x.toFixed(2)}" y="${(H - 4).toFixed(2)}" text-anchor="middle">${i.toString().padStart(2, '0')}</text>`;
    }).join('');

    const maxTemp = Math.max.apply(null, temps);
    const minTemp = Math.min.apply(null, temps);
    const maxIdx = temps.indexOf(maxTemp);
    const minIdx = temps.indexOf(minTemp);

    const tempLabels = [];
    if (maxIdx >= 0 && hours[maxIdx]) {
      const p = points[maxIdx];
      const offsetY = p.y < padY + 14 ? 18 : -10;
      tempLabels.push(`<text class="temp-label" x="${p.x.toFixed(2)}" y="${(p.y + offsetY).toFixed(2)}" text-anchor="middle">${Math.round(hours[maxIdx].temp)}°</text>`);
    }
    if (minIdx >= 0 && minIdx !== maxIdx && hours[minIdx]) {
      const p = points[minIdx];
      const offsetY = p.y > H - padY - 14 ? -18 : 20;
      tempLabels.push(`<text class="temp-label" x="${p.x.toFixed(2)}" y="${(p.y + offsetY).toFixed(2)}" text-anchor="middle">${Math.round(hours[minIdx].temp)}°</text>`);
    }

    const dots = points.map((p, i) => {
      const isMax = i === maxIdx;
      const isMin = i === minIdx;
      const isExtreme = isMax || isMin;
      const r = isExtreme ? 4.5 : 2.2;
      const fill = isMax ? '#FFC371' : isMin ? '#94A3B8' : 'rgba(255,255,255,0.45)';
      const delay = (0.8 + i * 0.015).toFixed(2);
      return `<circle class="point" cx="${p.x.toFixed(2)}" cy="${p.y.toFixed(2)}" r="${r}" fill="${fill}" style="animation-delay: ${delay}s"/>`;
    }).join('');

    return `
      <svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" xmlns="http://www.w3.org/2000/svg">
        <defs>
          <linearGradient id="lineGrad" x1="0" y1="0" x2="1" y2="0">
            <stop offset="0%"   stop-color="#94A3B8"/>
            <stop offset="50%"  stop-color="#FFC371"/>
            <stop offset="100%" stop-color="#F4A261"/>
          </linearGradient>
          <linearGradient id="fillGrad" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%"   stop-color="#FFC371" stop-opacity="0.35"/>
            <stop offset="100%" stop-color="#FFC371" stop-opacity="0"/>
          </linearGradient>
        </defs>
        ${gridLines.join('')}
        <path class="fill" d="${fillPath}" fill="url(#fillGrad)"/>
        <path class="line" d="${linePath}" stroke="url(#lineGrad)"/>
        ${dots}
        ${tempLabels.join('')}
        ${hourLabels}
      </svg>
    `;
  }

  load();
})();
